27	/**
28	 * A decoder that splits the received {@link ByteBuf}s by one or more
29	 * delimiters.  It is particularly useful for decoding the frames which ends
30	 * with a delimiter such as {@link Delimiters#nulDelimiter() NUL} or
31	 * {@linkplain Delimiters#lineDelimiter() newline characters}.
32	 *
33	 * <h3>Predefined delimiters</h3>
34	 * <p>
35	 * {@link Delimiters} defines frequently used delimiters for convenience' sake.
36	 *
37	 * <h3>Specifying more than one delimiter</h3>
38	 * <p>
39	 * {@link DelimiterBasedFrameDecoder} allows you to specify more than one
40	 * delimiter.  If more than one delimiter is found in the buffer, it chooses
41	 * the delimiter which produces the shortest frame.  For example, if you have
42	 * the following data in the buffer:
43	 * <pre>
44	 * +--------------+
45	 * | ABC\nDEF\r\n |
46	 * +--------------+
47	 * </pre>
48	 * a {@link DelimiterBasedFrameDecoder}({@link Delimiters#lineDelimiter() Delimiters.lineDelimiter()})
49	 * will choose {@code '\n'} as the first delimiter and produce two frames:
50	 * <pre>
51	 * +-----+-----+
52	 * | ABC | DEF |
53	 * +-----+-----+
54	 * </pre>
55	 * rather than incorrectly choosing {@code '\r\n'} as the first delimiter:
56	 * <pre>
57	 * +----------+
58	 * | ABC\nDEF |
59	 * +----------+
60	 * </pre>
61	 */
62	public class DelimiterBasedFrameDecoder extends ByteToMessageDecoder {
63	
64	    /** Size of the first window searched when more than one delimiter is configured. */
65	    private static final int INITIAL_SCAN_WINDOW = 64;
66	
67	    private final ByteBuf[] delimiters;
68	    private final int maxDelimiterLength;
69	    private final int maxFrameLength;
70	    private final boolean stripDelimiter;
71	    private final boolean failFast;
72	    private boolean discardingTooLongFrame;
73	    private int tooLongFrameLength;
74	    /** Set only when decoding with "\n" and "\r\n" as the delimiter.  */
75	    private final LineBasedFrameDecoder lineBasedDecoder;
76	    /**
77	     * Last scan position, relative to the reader index, at which no delimiter could be found.
78	     * Resuming from this offset avoids rescanning the whole buffer from the reader index on
79	     * every {@link #decode(ChannelHandlerContext, ByteBuf)} call.
80	     */
81	    private int scanOffset;
82	
83	    /**
84	     * Creates a new instance.
85	     *
86	     * @param maxFrameLength  the maximum length of the decoded frame.
87	     *                        A {@link TooLongFrameException} is thrown if
88	     *                        the length of the frame exceeds this value.
89	     * @param delimiter  the delimiter
90	     */
91	    public DelimiterBasedFrameDecoder(int maxFrameLength, ByteBuf delimiter) {
92	        this(maxFrameLength, true, delimiter);
93	    }
94	
95	    /**
96	     * Creates a new instance.
97	     *
98	     * @param maxFrameLength  the maximum length of the decoded frame.
99	     *                        A {@link TooLongFrameException} is thrown if
100	     *                        the length of the frame exceeds this value.
101	     * @param stripDelimiter  whether the decoded frame should strip out the
102	     *                        delimiter or not
103	     * @param delimiter  the delimiter
104	     */
105	    public DelimiterBasedFrameDecoder(
106	            int maxFrameLength, boolean stripDelimiter, ByteBuf delimiter) {
107	        this(maxFrameLength, stripDelimiter, true, delimiter);
108	    }
109	
110	    /**
111	     * Creates a new instance.
112	     *
113	     * @param maxFrameLength  the maximum length of the decoded frame.
114	     *                        A {@link TooLongFrameException} is thrown if
115	     *                        the length of the frame exceeds this value.
116	     * @param stripDelimiter  whether the decoded frame should strip out the
117	     *                        delimiter or not
118	     * @param failFast  If <tt>true</tt>, a {@link TooLongFrameException} is
119	     *                  thrown as soon as the decoder notices the length of the
120	     *                  frame will exceed <tt>maxFrameLength</tt> regardless of
121	     *                  whether the entire frame has been read.
122	     *                  If <tt>false</tt>, a {@link TooLongFrameException} is
123	     *                  thrown after the entire frame that exceeds
124	     *                  <tt>maxFrameLength</tt> has been read.
125	     * @param delimiter  the delimiter
126	     */
127	    public DelimiterBasedFrameDecoder(
128	            int maxFrameLength, boolean stripDelimiter, boolean failFast,
129	            ByteBuf delimiter) {
130	        this(maxFrameLength, stripDelimiter, failFast, new ByteBuf[] {
131	                delimiter.slice(delimiter.readerIndex(), delimiter.readableBytes())});
132	    }
133	
134	    /**
135	     * Creates a new instance.
136	     *
137	     * @param maxFrameLength  the maximum length of the decoded frame.
138	     *                        A {@link TooLongFrameException} is thrown if
139	     *                        the length of the frame exceeds this value.
140	     * @param delimiters  the delimiters
141	     */
142	    public DelimiterBasedFrameDecoder(int maxFrameLength, ByteBuf... delimiters) {
143	        this(maxFrameLength, true, delimiters);
144	    }
145	
146	    /**
147	     * Creates a new instance.
148	     *
149	     * @param maxFrameLength  the maximum length of the decoded frame.
150	     *                        A {@link TooLongFrameException} is thrown if
151	     *                        the length of the frame exceeds this value.
152	     * @param stripDelimiter  whether the decoded frame should strip out the
153	     *                        delimiter or not
154	     * @param delimiters  the delimiters
155	     */
156	    public DelimiterBasedFrameDecoder(
157	            int maxFrameLength, boolean stripDelimiter, ByteBuf... delimiters) {
158	        this(maxFrameLength, stripDelimiter, true, delimiters);
159	    }
160	
161	    /**
162	     * Creates a new instance.
163	     *
164	     * @param maxFrameLength  the maximum length of the decoded frame.
165	     *                        A {@link TooLongFrameException} is thrown if
166	     *                        the length of the frame exceeds this value.
167	     * @param stripDelimiter  whether the decoded frame should strip out the
168	     *                        delimiter or not
169	     * @param failFast  If <tt>true</tt>, a {@link TooLongFrameException} is
170	     *                  thrown as soon as the decoder notices the length of the
171	     *                  frame will exceed <tt>maxFrameLength</tt> regardless of
172	     *                  whether the entire frame has been read.
173	     *                  If <tt>false</tt>, a {@link TooLongFrameException} is
174	     *                  thrown after the entire frame that exceeds
175	     *                  <tt>maxFrameLength</tt> has been read.
176	     * @param delimiters  the delimiters
177	     */
178	    public DelimiterBasedFrameDecoder(
179	            int maxFrameLength, boolean stripDelimiter, boolean failFast, ByteBuf... delimiters) {
180	        validateMaxFrameLength(maxFrameLength);
181	        ObjectUtil.checkNonEmpty(delimiters, "delimiters");
182	
183	        if (isLineBased(delimiters) && !isSubclass()) {
184	            lineBasedDecoder = new LineBasedFrameDecoder(maxFrameLength, stripDelimiter, failFast);
185	            this.delimiters = null;
186	            this.maxDelimiterLength = 0;
187	        } else {
188	            this.delimiters = new ByteBuf[delimiters.length];
189	            int maxDelimiterLength = 0;
190	            for (int i = 0; i < delimiters.length; i ++) {
191	                ByteBuf d = delimiters[i];
192	                validateDelimiter(d);
193	                this.delimiters[i] = d.slice(d.readerIndex(), d.readableBytes());
194	                maxDelimiterLength = Math.max(maxDelimiterLength, this.delimiters[i].readableBytes());
195	            }
196	            this.maxDelimiterLength = maxDelimiterLength;
197	            lineBasedDecoder = null;
198	        }
199	        this.maxFrameLength = maxFrameLength;
200	        this.stripDelimiter = stripDelimiter;
201	        this.failFast = failFast;
202	    }
203	
204	    /** Returns true if the delimiters are "\n" and "\r\n".  */
205	    private static boolean isLineBased(final ByteBuf[] delimiters) {
206	        if (delimiters.length != 2) {
207	            return false;
208	        }
209	        ByteBuf a = delimiters[0];
210	        ByteBuf b = delimiters[1];
211	        if (a.capacity() < b.capacity()) {
212	            a = delimiters[1];
213	            b = delimiters[0];
214	        }
215	        return a.capacity() == 2 && b.capacity() == 1
216	                && a.getByte(0) == '\r' && a.getByte(1) == '\n'
217	                && b.getByte(0) == '\n';
218	    }
219	
220	    /**
221	     * Return {@code true} if the current instance is a subclass of DelimiterBasedFrameDecoder
222	     */
223	    private boolean isSubclass() {
224	        return getClass() != DelimiterBasedFrameDecoder.class;
225	    }
