227	    @Override
228	    protected final void decode(ChannelHandlerContext ctx, ByteBuf in, List<Object> out) throws Exception {
229	        Object decoded = decode(ctx, in);
230	        if (decoded != null) {
231	            out.add(decoded);
232	        }
233	    }
234	
235	    /**
236	     * Create a frame out of the {@link ByteBuf} and return it.
237	     *
238	     * @param   ctx             the {@link ChannelHandlerContext} which this {@link ByteToMessageDecoder} belongs to
239	     * @param   buffer          the {@link ByteBuf} from which to read data
240	     * @return  frame           the {@link ByteBuf} which represent the frame or {@code null} if no frame could
241	     *                          be created.
242	     */
243	    protected Object decode(ChannelHandlerContext ctx, ByteBuf buffer) throws Exception {
244	        if (lineBasedDecoder != null) {
245	            return lineBasedDecoder.decode(ctx, buffer);
246	        }
247	        // Try all delimiters and choose the delimiter which yields the shortest frame.
248	        int minFrameLength = Integer.MAX_VALUE;
249	        ByteBuf minDelim = null;
250	        final int readableBytes = buffer.readableBytes();
251	        // Searching every delimiter through the whole remaining buffer would cost O(readableBytes) per delimiter
252	        // even if another delimiter matches right at the start, which is quadratic when many small frames are
253	        // contained in one large buffer. With more than one delimiter we therefore search in windows that double in
254	        // size, so the work done is bounded by the length of the frame we find rather than by the buffer size.
255	        long window = delimiters.length == 1 ? readableBytes : Math.max(INITIAL_SCAN_WINDOW, maxDelimiterLength);
256	        int from = scanOffset;
257	        while (from < readableBytes) {
258	            // Extend the region by maxDelimiterLength - 1 so a delimiter that starts inside the window but ends
259	            // after it is still found.
260	            int end = (int) Math.min(readableBytes, from + window + maxDelimiterLength - 1);
261	            ByteBuf region = buffer.slice(buffer.readerIndex() + from, end - from);
262	            for (ByteBuf delim: delimiters) {
263	                int index = ByteBufUtil.indexOf(delim, region);
264	                if (index >= 0 && from + index < minFrameLength) {
265	                    minFrameLength = from + index;
266	                    minDelim = delim;
267	                }
268	            }
269	            if (minDelim != null && (end == readableBytes || minFrameLength < from + window)) {
270	                // All matches that start before the current minimum are guaranteed to be inside the region.
271	                break;
272	            }
273	            // Either nothing was found, or the only matches start in the overlap and another delimiter might
274	            // match earlier. Continue with the next window, which will find those matches again.
275	            minFrameLength = Integer.MAX_VALUE;
276	            minDelim = null;
277	            from = (int) Math.min(readableBytes, from + window);
278	            window = Math.min(window << 1, Integer.MAX_VALUE);
279	        }
280	
281	        if (minDelim != null) {
282	            // A delimiter was found; the next decode() call starts scanning fresh data only.
283	            scanOffset = 0;
284	            int minDelimLength = minDelim.capacity();
285	            ByteBuf frame;
286	
287	            if (discardingTooLongFrame) {
288	                // We've just finished discarding a very large frame.
289	                // Go back to the initial state.
290	                discardingTooLongFrame = false;
291	                buffer.skipBytes(minFrameLength + minDelimLength);
292	
293	                int tooLongFrameLength = this.tooLongFrameLength;
294	                this.tooLongFrameLength = 0;
295	                if (!failFast) {
296	                    fail(tooLongFrameLength);
297	                }
298	                return null;
299	            }
300	
301	            if (minFrameLength > maxFrameLength) {
302	                // Discard read frame.
303	                buffer.skipBytes(minFrameLength + minDelimLength);
304	                fail(minFrameLength);
305	                return null;
306	            }
307	
308	            if (stripDelimiter) {
309	                frame = buffer.readRetainedSlice(minFrameLength);
310	                buffer.skipBytes(minDelimLength);
311	            } else {
312	                frame = buffer.readRetainedSlice(minFrameLength + minDelimLength);
313	            }
314	
315	            return frame;
316	        } else {
317	            // The buffer may end with the first bytes of a delimiter whose remaining bytes were not received yet.
318	            // They are neither counted as part of the frame nor discarded.
319	            int frameBytes = readableBytes - partialDelimiterLength(buffer);
320	            if (!discardingTooLongFrame) {
321	                if (frameBytes > maxFrameLength) {
322	                    // Discard the content of the buffer until a delimiter is found.
323	                    tooLongFrameLength = frameBytes;
324	                    buffer.skipBytes(frameBytes);
325	                    discardingTooLongFrame = true;
326	                    scanOffset = 0;
327	                    if (failFast) {
328	                        fail(tooLongFrameLength);
329	                    }
330	                } else {
331	                    // No delimiter found yet. Remember how far we've already scanned so the next
332	                    // call doesn't rescan bytes that cannot possibly contain the start of a match.
333	                    scanOffset = Math.max(0, readableBytes - maxDelimiterLength + 1);
334	                }
335	            } else {
336	                // Still discarding the buffer since a delimiter is not found.
337	                tooLongFrameLength += frameBytes;
338	                buffer.skipBytes(frameBytes);
339	                scanOffset = 0;
340	            }
341	            return null;
342	        }
343	    }
344	
345	    /**
346	     * Returns the length of the longest suffix of the readable bytes that is the beginning of a delimiter.
347	     */
348	    private int partialDelimiterLength(ByteBuf buffer) {
349	        int readableBytes = buffer.readableBytes();
350	        int partialLength = 0;
351	        for (ByteBuf delim: delimiters) {
352	            for (int length = Math.min(delim.capacity() - 1, readableBytes); length > partialLength; length--) {
353	                if (ByteBufUtil.equals(buffer, buffer.writerIndex() - length, delim, 0, length)) {
354	                    partialLength = length;
355	                    break;
356	                }
357	            }
358	        }
359	        return partialLength;
360	    }
361	
362	    private void fail(long frameLength) {
363	        if (frameLength > 0) {
364	            throw new TooLongFrameException(
365	                            "frame length exceeds " + maxFrameLength +
366	                            ": " + frameLength + " - discarded");
367	        } else {
368	            throw new TooLongFrameException(
369	                            "frame length exceeds " + maxFrameLength +
370	                            " - discarding");
371	        }
372	    }
373	
374	    private static void validateDelimiter(ByteBuf delimiter) {
375	        ObjectUtil.checkNotNull(delimiter, "delimiter");
376	        if (!delimiter.isReadable()) {
377	            throw new IllegalArgumentException("empty delimiter");
378	        }
379	    }
380	
381	    private static void validateMaxFrameLength(int maxFrameLength) {
382	        checkPositive(maxFrameLength, "maxFrameLength");
383	    }
384	}
