178	        if (!name().equals(that.name())) {
179	            return false;
180	        }
181	
182	        if (path() == null) {
183	            if (that.path() != null) {
184	                return false;
185	            }
186	        } else if (that.path() == null) {
187	            return false;
188	        } else if (!path().equals(that.path())) {
189	            return false;
190	        }
191	
192	        if (domain() == null) {
193	            if (that.domain() != null) {
194	                return false;
195	            }
196	        } else {
197	            return domain().equalsIgnoreCase(that.domain());
198	        }
199	
200	        return true;
201	    }
202	
203	    @Override
204	    public int compareTo(Cookie c) {
205	        int v = name().compareTo(c.name());
206	        if (v != 0) {
207	            return v;
208	        }
209	
210	        if (path() == null) {
211	            if (c.path() != null) {
212	                return -1;
213	            }
214	        } else if (c.path() == null) {
215	            return 1;
216	        } else {
217	            v = path().compareTo(c.path());
218	            if (v != 0) {
219	                return v;
220	            }
221	        }
222	
223	        if (domain() == null) {
224	            if (c.domain() != null) {
225	                return -1;
226	            }
227	        } else if (c.domain() == null) {
228	            return 1;
229	        } else {
230	            v = domain().compareToIgnoreCase(c.domain());
231	            return v;
232	        }
233	
234	        return 0;
235	    }
