442	    /**
443	     * Fetch charset from Content-Type header value.
444	     *
445	     * @param contentTypeValue Content-Type header value to parse
446	     * @param defaultCharset   result to use in case of empty, incorrect or doesn't contain required part header value
447	     * @return the charset from message's Content-Type header or {@code defaultCharset}
448	     * if charset is not presented or unparsable
449	     */
450	    public static Charset getCharset(CharSequence contentTypeValue, Charset defaultCharset) {
451	        if (contentTypeValue != null) {
452	            CharSequence charsetRaw = getCharsetAsSequence(contentTypeValue);
453	            if (charsetRaw != null) {
454	                // Remove only the trailing optional whitespace (OWS) that RFC 9110 allows before
455	                // the semicolon starting the next parameter, see
456	                // https://www.rfc-editor.org/rfc/rfc9110#section-5.6.6
457	                // Leading whitespace after '=' is not grammar-legal and is deliberately kept, so
458	                // such values keep failing the charset lookup below.
459	                int end = charsetRaw.length();
460	                while (end > 0 && isOws(charsetRaw.charAt(end - 1))) {
461	                    end--;
462	                }
463	                if (end < charsetRaw.length()) {
464	                    charsetRaw = charsetRaw.subSequence(0, end);
465	                }
466	                if (charsetRaw.length() > 2) { // at least contains 2 quotes(")
467	                    if (charsetRaw.charAt(0) == '"' && charsetRaw.charAt(charsetRaw.length() - 1) == '"') {
468	                        charsetRaw = charsetRaw.subSequence(1, charsetRaw.length() - 1);
469	                    }
470	                }
471	                try {
472	                    return Charset.forName(charsetRaw.toString());
473	                } catch (IllegalCharsetNameException | UnsupportedCharsetException ignored) {
474	                    // just return the default charset
475	                }
476	            }
477	        }
478	        return defaultCharset;
479	    }
