481	    /**
482	     * Whether the given character is optional whitespace (OWS) as defined by
483	     * <a href="https://www.rfc-editor.org/rfc/rfc9110#section-5.6.3">RFC 9110 section 5.6.3</a>.
484	     */
485	    private static boolean isOws(char c) {
486	        return c == ' ' || c == '\t';
487	    }
