496	     * @return the {@code CharSequence} with charset from message's Content-Type header
497	     * or {@code null} if charset is not presented
498	     * @deprecated use {@link #getCharsetAsSequence(HttpMessage)}
499	     */
500	    @Deprecated
501	    public static CharSequence getCharsetAsString(HttpMessage message) {
502	        return getCharsetAsSequence(message);
