505	    /**
506	     * Fetch charset from message's Content-Type header as a char sequence.
507	     *
508	     * A lot of sites/possibly clients have charset="CHARSET", for example charset="utf-8". Or "utf8" instead of "utf-8"
509	     * This is not according to standard, but this method provide an ability to catch desired mistakes manually in code
510	     *
511	     * @return the {@code CharSequence} with charset from message's Content-Type header
512	     * or {@code null} if charset is not presented
513	     */
514	    public static CharSequence getCharsetAsSequence(HttpMessage message) {
515	        CharSequence contentTypeValue = message.headers().get(HttpHeaderNames.CONTENT_TYPE);
516	        if (contentTypeValue != null) {
517	            return getCharsetAsSequence(contentTypeValue);
518	        } else {
519	            return null;
520	        }
