523	    /**
524	     * Fetch charset from Content-Type header value as a char sequence.
525	     *
526	     * A lot of sites/possibly clients have charset="CHARSET", for example charset="utf-8". Or "utf8" instead of "utf-8"
527	     * This is not according to standard, but this method provide an ability to catch desired mistakes manually in code
528	     *
529	     * @param contentTypeValue Content-Type header value to parse
530	     * @return the {@code CharSequence} with charset from message's Content-Type header
531	     * or {@code null} if charset is not presented
532	     * @throws NullPointerException in case if {@code contentTypeValue == null}
533	     */
534	    public static CharSequence getCharsetAsSequence(CharSequence contentTypeValue) {
535	        ObjectUtil.checkNotNull(contentTypeValue, "contentTypeValue");
536	
537	        int indexOfCharset = AsciiString.indexOfIgnoreCaseAscii(contentTypeValue, CHARSET_EQUALS, 0);
538	        if (indexOfCharset == AsciiString.INDEX_NOT_FOUND) {
539	            return null;
540	        }
541	
542	        int indexOfEncoding = indexOfCharset + CHARSET_EQUALS.length();
543	        if (indexOfEncoding < contentTypeValue.length()) {
544	            CharSequence charsetCandidate = contentTypeValue.subSequence(indexOfEncoding, contentTypeValue.length());
545	            int indexOfSemicolon = AsciiString.indexOfIgnoreCaseAscii(charsetCandidate, SEMICOLON, 0);
546	            if (indexOfSemicolon == AsciiString.INDEX_NOT_FOUND) {
547	                return charsetCandidate;
548	            }
549	
550	            return charsetCandidate.subSequence(0, indexOfSemicolon);
551	        }
552	
553	        return null;
554	    }
