576	    /**
577	     * Fetch MIME type part from Content-Type header value as a char sequence.
578	     *
579	     * @param contentTypeValue Content-Type header value to parse
580	     * @return the MIME type as a {@code CharSequence} from message's Content-Type header
581	     * or {@code null} if content-type header or MIME type part of this header are not presented
582	     * <p/>
583	     * "content-type: text/html; charset=utf-8" - "text/html" will be returned <br/>
584	     * "content-type: text/html" - "text/html" will be returned <br/>
585	     * "content-type: empty header - {@code null} we be returned
586	     * @throws NullPointerException in case if {@code contentTypeValue == null}
587	     */
588	    public static CharSequence getMimeType(CharSequence contentTypeValue) {
589	        ObjectUtil.checkNotNull(contentTypeValue, "contentTypeValue");
590	
591	        int indexOfSemicolon = AsciiString.indexOfIgnoreCaseAscii(contentTypeValue, SEMICOLON, 0);
592	        if (indexOfSemicolon != AsciiString.INDEX_NOT_FOUND) {
593	            // Remove the trailing optional whitespace (OWS) that RFC 9110 allows before the semicolon
594	            // starting the next parameter, see https://www.rfc-editor.org/rfc/rfc9110#section-8.3.1
595	            int end = indexOfSemicolon;
596	            while (end > 0 && isOws(contentTypeValue.charAt(end - 1))) {
597	                end--;
598	            }
599	            return contentTypeValue.subSequence(0, end);
600	        } else {
601	            return contentTypeValue.length() > 0 ? contentTypeValue : null;
602	        }
603	    }
