605	    /**
606	     * Formats the host string of an address so it can be used for computing an HTTP component
607	     * such as a URL or a Host header
608	     *
609	     * @param addr the address
610	     * @return the formatted String
611	     */
612	    public static String formatHostnameForHttp(InetSocketAddress addr) {
613	        String hostString = NetUtil.getHostname(addr);
614	        if (NetUtil.isValidIpV6Address(hostString)) {
615	            if (!addr.isUnresolved()) {
616	                hostString = NetUtil.toAddressString(addr.getAddress());
617	            } else if (hostString.charAt(0) == '[' && hostString.charAt(hostString.length() - 1) == ']') {
618	                // If IPv6 address already contains brackets, let's return as is.
619	                return hostString;
620	            }
621	
622	            return '[' + hostString + ']';
623	        }
624	        return hostString;
625	    }
