627	    /**
628	     * Validates, and optionally extracts the content length from headers. This method is not intended for
629	     * general use, but is here to be shared between HTTP/1 and HTTP/2 parsing.
630	     *
631	     * @param contentLengthFields the content-length header fields.
632	     * @param isHttp10OrEarlier unused
633	     * @param allowDuplicateContentLengths {@code true}  if multiple, identical-value content lengths should be allowed.
634	     * @return the normalized content length from the headers or {@code -1} if the fields were empty.
635	     * @throws IllegalArgumentException if the content-length fields are not valid
636	     */
637	    public static long normalizeAndGetContentLength(
638	            List<? extends CharSequence> contentLengthFields, @SuppressWarnings("unused") boolean isHttp10OrEarlier,
639	            boolean allowDuplicateContentLengths) {
640	        if (contentLengthFields.isEmpty()) {
641	            return -1;
642	        }
643	
644	        // Guard against multiple Content-Length headers as stated in
645	        // https://tools.ietf.org/html/rfc7230#section-3.3.2:
646	        //
647	        // If a message is received that has multiple Content-Length header
648	        //   fields with field-values consisting of the same decimal value, or a
649	        //   single Content-Length header field with a field value containing a
650	        //   list of identical decimal values (e.g., "Content-Length: 42, 42"),
651	        //   indicating that duplicate Content-Length header fields have been
652	        //   generated or combined by an upstream message processor, then the
653	        //   recipient MUST either reject the message as invalid or replace the
654	        //   duplicated field-values with a single valid Content-Length field
655	        //   containing that decimal value prior to determining the message body
656	        //   length or forwarding the message.
657	        String firstField = contentLengthFields.get(0).toString();
658	        boolean multipleContentLengths =
659	                contentLengthFields.size() > 1 || firstField.indexOf(COMMA) >= 0;
660	
661	        if (multipleContentLengths) {
662	            if (allowDuplicateContentLengths) {
663	                // Find and enforce that all Content-Length values are the same
664	                String firstValue = null;
665	                for (CharSequence field : contentLengthFields) {
666	                    String[] tokens = field.toString().split(COMMA_STRING, -1);
667	                    for (String token : tokens) {
668	                        String trimmed = token.trim();
669	                        if (firstValue == null) {
670	                            firstValue = trimmed;
671	                        } else if (!trimmed.equals(firstValue)) {
672	                            throw new IllegalArgumentException(
673	                                    "Multiple Content-Length values found: " + contentLengthFields);
674	                        }
675	                    }
676	                }
677	                // Replace the duplicated field-values with a single valid Content-Length field
678	                firstField = firstValue;
679	            } else {
680	                // Reject the message as invalid
681	                throw new IllegalArgumentException(
682	                        "Multiple Content-Length values found: " + contentLengthFields);
683	            }
684	        }
685	        // Ensure we not allow sign as part of the content-length:
686	        // See https://github.com/squid-cache/squid/security/advisories/GHSA-qf3v-rc95-96j5
687	        if (firstField.isEmpty() || !Character.isDigit(firstField.charAt(0))) {
688	            // Reject the message as invalid
689	            throw new IllegalArgumentException(
690	                    "Content-Length value is not a number: " + firstField);
691	        }
692	        try {
693	            final long value = Long.parseLong(firstField);
694	            return checkPositiveOrZero(value, "Content-Length value");
695	        } catch (NumberFormatException e) {
696	            // Reject the message as invalid
697	            throw new IllegalArgumentException(
698	                    "Content-Length value is not a number: " + firstField, e);
699	        }
700	    }
