702	    /**
703	     * Validate a <a href="https://tools.ietf.org/html/rfc7230#section-3.2.6">token</a> contains only allowed
704	     * characters.
705	     * <p>
706	     * The <a href="https://tools.ietf.org/html/rfc2616#section-2.2">token</a> format is used for variety of HTTP
707	     * components, like  <a href="https://tools.ietf.org/html/rfc6265#section-4.1.1">cookie-name</a>,
708	     * <a href="https://tools.ietf.org/html/rfc7230#section-3.2.6">field-name</a> of a
709	     * <a href="https://tools.ietf.org/html/rfc7230#section-3.2">header-field</a>, or
710	     * <a href="https://tools.ietf.org/html/rfc7231#section-4">request method</a>.
711	     *
712	     * @param token the token to validate.
713	     * @return the index of the first invalid token character found, or {@code -1} if there are none.
714	     */
715	    static int validateToken(CharSequence token) {
716	        if (token instanceof AsciiString) {
717	            return validateAsciiStringToken((AsciiString) token);
718	        }
719	        return validateCharSequenceToken(token);
720	    }
