722	    /**
723	     * Validate that an {@link AsciiString} contain onlu valid
724	     * <a href="https://tools.ietf.org/html/rfc7230#section-3.2.6">token</a> characters.
725	     *
726	     * @param token the ascii string to validate.
727	     */
728	    private static int validateAsciiStringToken(AsciiString token) {
729	        byte[] array = token.array();
730	        for (int i = token.arrayOffset(), len = token.arrayOffset() + token.length(); i < len; i++) {
731	            if (!isValidTokenChar(array[i])) {
732	                return i - token.arrayOffset();
733	            }
734	        }
735	        return -1;
736	    }
737	
738	    /**
739	     * Validate that a {@link CharSequence} contain onlu valid
740	     * <a href="https://tools.ietf.org/html/rfc7230#section-3.2.6">token</a> characters.
741	     *
742	     * @param token the character sequence to validate.
743	     */
744	    private static int validateCharSequenceToken(CharSequence token) {
745	        for (int i = 0, len = token.length(); i < len; i++) {
746	            int value = token.charAt(i);
747	            // 1. Check for truncation (anything above 255)
748	            // 2. Check against the BitSet (isValidTokenChar handles 128-255 via bit < 0)
749	            if (value > 0xFF || !isValidTokenChar((byte) value)) {
750	                return i;
751	            }
752	        }
753	        return -1;
754	    }
