185	    private static int toDecimal(final int value) {
186	        if (value < '0' || value > '9') {
187	            throw new IllegalArgumentException("Invalid version number, only 0-9 (0x30-0x39) allowed," +
188	                    " but received a '" + (char) value + "' (0x" + Integer.toHexString(value) + ")");
189	        }
