198	     * <a href="https://en.wikipedia.org/wiki/Internet_Content_Adaptation_Protocol">ICAP</a>
199	     *
200	     * @param keepAliveDefault
201	     *        {@code true} if and only if the connection is kept alive unless
202	     *        the {@code "Connection"} header is set to {@code "close"} explicitly.
203	     */
204	    public HttpVersion(
205	            String protocolName, int majorVersion, int minorVersion,
206	            boolean keepAliveDefault) {
207	        this(protocolName, majorVersion, minorVersion, keepAliveDefault, false);
208	    }
209	
210	    private HttpVersion(
211	            String protocolName, int majorVersion, int minorVersion,
212	            boolean keepAliveDefault, boolean bytes) {
213	        // See the comment in the (text, strict, keepAliveDefault) constructor for why this needs
214	        // an explicit Locale.US: avoids the Turkish-locale 'i' -> 'İ' corruption.
215	        ObjectUtil.checkNotNull(protocolName, "protocolName");
216	        if (protocolName.isEmpty()) {
217	            throw new IllegalArgumentException("protocolName must not be empty");
218	        }
219	        protocolName = protocolName.toUpperCase(Locale.US);
220	
221	        if (hasControlOrWhitespace(protocolName, protocolName.length())) {
222	            throw new IllegalArgumentException("invalid character in protocolName");
223	        }
224	
225	        checkPositiveOrZero(majorVersion, "majorVersion");
226	        checkPositiveOrZero(minorVersion, "minorVersion");
227	
228	        this.protocolName = protocolName;
229	        this.majorVersion = majorVersion;
230	        this.minorVersion = minorVersion;
231	        text = protocolName + '/' + majorVersion + '.' + minorVersion;
232	        this.keepAliveDefault = keepAliveDefault;
233	
234	        if (bytes) {
235	            this.bytes = text.getBytes(CharsetUtil.US_ASCII);
236	        } else {
237	            this.bytes = null;
238	        }
239	    }
240	
241	    /**
242	     * Returns the name of the protocol such as {@code "HTTP"} in {@code "HTTP/1.0"}.
243	     */
244	    public String protocolName() {
245	        return protocolName;
246	    }
247	
248	    /**
249	     * Returns the name of the protocol such as {@code 1} in {@code "HTTP/1.0"}.
250	     */
251	    public int majorVersion() {
252	        return majorVersion;
253	    }
254	
255	    /**
256	     * Returns the name of the protocol such as {@code 0} in {@code "HTTP/1.0"}.
257	     */
258	    public int minorVersion() {
259	        return minorVersion;
260	    }
261	
262	    /**
263	     * Returns the full protocol version text such as {@code "HTTP/1.0"}.
264	     */
265	    public String text() {
266	        return text;
267	    }
268	
269	    /**
270	     * Returns {@code true} if and only if the connection is kept alive unless
271	     * the {@code "Connection"} header is set to {@code "close"} explicitly.
272	     */
273	    public boolean isKeepAliveDefault() {
274	        return keepAliveDefault;
275	    }
276	
277	    /**
278	     * Returns the full protocol version text such as {@code "HTTP/1.0"}.
279	     */
280	    @Override
281	    public String toString() {
282	        return text();
283	    }
284	
285	    @Override
286	    public int hashCode() {
287	        return (protocolName().hashCode() * 31 + majorVersion()) * 31 +
288	               minorVersion();
289	    }
290	
291	    @Override
292	    public boolean equals(Object o) {
293	        if (!(o instanceof HttpVersion)) {
294	            return false;
295	        }
296	
297	        HttpVersion that = (HttpVersion) o;
298	        return minorVersion() == that.minorVersion() &&
299	               majorVersion() == that.majorVersion() &&
300	               protocolName().equals(that.protocolName());
301	    }
302	
303	    @Override
304	    public int compareTo(HttpVersion o) {
305	        int v = protocolName().compareTo(o.protocolName());
306	        if (v != 0) {
307	            return v;
308	        }
309	
310	        v = majorVersion() - o.majorVersion();
311	        if (v != 0) {
312	            return v;
313	        }
314	
315	        return minorVersion() - o.minorVersion();
316	    }
317	
318	    void encode(ByteBuf buf) {
319	        if (bytes == null) {
320	            buf.writeCharSequence(text, CharsetUtil.US_ASCII);
321	        } else {
322	            buf.writeBytes(bytes);
323	        }
324	    }
