52	    /**
53	     * Proposed default MINSIZE as 16 KB.
54	     */
55	    public static final long MINSIZE = 0x4000;
56	    /**
57	     * Proposed default MAXSIZE = -1 as UNLIMITED
58	     */
59	    public static final long MAXSIZE = -1;
