339	    @Override
340	    public void cleanRequestHttpDatas(HttpRequest request) {
341	        cleanRequestHttpData(request);
342	    }
343	
344	    @Override
345	    public void cleanAllHttpDatas() {
346	        cleanAllHttpData();
347	    }
